function validate([head]) {
  if (!Array.isArray(head) || head.length < 1 || head.length > 10000) return 'The list needs 1 to 10^4 nodes.';
  if (head.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each node value is an integer between 1 and 10^9.';
  return null;
}

