function nextLargerNodes(head) {
  const values = [];
  const answer = [];
  const stack = [];

  for (let node = head; node !== null; node = node.next) {
    const index = values.length;
    values.push(node.val);
    answer.push(0);
    while (stack.length > 0 && values[stack[stack.length - 1]] < node.val) {
      const waiting = stack.pop();
      answer[waiting] = node.val;
    }
    stack.push(index);
  }
  return answer;
}

