function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const top = rand() < 0.6 ? 5 : 1000000000;
    return [Array.from({ length: int(1, 8) }, () => int(1, top))];
  }
  const n = 2000;
  const shape = int(0, 2);
  if (shape === 0) return [Array.from({ length: n }, () => int(1, 1000000000))];
  if (shape === 1) {
    // Long falling runs that are resolved together by a later spike.
    const list = [];
    while (list.length < n) {
      const run = int(1, 300);
      let value = int(500000000, 999999999);
      for (let k = 0; k < run && list.length < n - 1; k++) { list.push(value); value = Math.max(1, value - int(0, 1000000)); }
      list.push(int(1, 1000000000));
    }
    return [list.slice(0, n)];
  }
  return [Array.from({ length: n }, () => int(1, 50))];
}
